<?php declare(strict_types=1); ?>
<section class="view hidden" id="view-admin-clubs" data-title="Manage clubs" data-section="Administration"><div class="page-heading"><div><span class="eyebrow gold-eyebrow">CONTENT MANAGEMENT</span><h1>Manage clubs</h1><p class="muted">Review campus communities. Editing will be added in a later stage.</p></div><button class="button button-dark" data-view="admin-club-form">Add club <span>+</span></button></div><form class="toolbar" method="get" action="index.php"><input type="hidden" name="view" value="admin-clubs"><div class="search-box"><span>⌕</span><input name="q" type="search" value="<?= e($_GET['q'] ?? '') ?>" placeholder="Search clubs..." aria-label="Search clubs"></div><select name="category" aria-label="Filter club category"><option value="">All categories</option><?php foreach (['Academic', 'Creative', 'Social', 'Sports'] as $category): ?><option value="<?= e($category) ?>" <?= strtolower((string) ($_GET['category'] ?? '')) === strtolower($category) ? 'selected' : '' ?>><?= e($category) ?></option><?php endforeach; ?></select><button class="button button-outline" type="submit">Search</button></form><?php if ($dataError !== null): ?><div class="panel empty-state"><h3>Clubs are temporarily unavailable.</h3><p class="muted"><?= e($dataError) ?></p></div><?php elseif ($clubs === []): ?><div class="panel empty-state"><h3>No clubs found</h3><p class="muted">Try a different search.</p></div><?php else: ?><div class="panel admin-table"><div class="table-row table-head"><span>Club</span><span>Category</span><span>Contact</span><span>Status</span><span>Actions</span></div><?php foreach ($clubs as $club): $tone = club_tone((string) $club['category']); ?><div class="table-row"><span class="table-event"><span class="club-avatar small <?= e($tone) ?>">✦</span><strong><?= e($club['name']) ?><small><?= e($club['description']) ?></small></strong></span><span><?= e($club['category']) ?></span><span><?= e($club['contact_email'] ?: 'Not listed') ?></span><span class="tag tag-green">Active</span><span class="row-actions"><a class="text-button" data-view="club-details" data-route="true" href="index.php?view=club-details&amp;id=<?= (int) $club['club_id'] ?>">View</a></span></div><?php endforeach; ?></div><?php endif; ?></section>
